\begin{tikzpicture} \begin{axis}[ view={35}{20}, width=0.95\textwidth, height=0.65\textwidth, grid=none, axis lines=center, xlabel={\(x\)}, ylabel={}, zlabel={}, xtick={0, 3, 3.5, 6}, xticklabels={\(a\), \(x\), \(x+\Delta x\), \(b\)}, ytick=\empty, ztick=\empty, xmin=-0.5, xmax=7.5, ymin=-2.5, ymax=2.5, zmin=-2.5, zmax=2.5, z buffer=sort ]
% 1. Back portion of the solid (x from 0 to 3) \addplot3[ surf, domain=0:3, y domain=0:360, samples=15, samples y=36, fill=gray!10, faceted color=gray!40, line width=0.1pt ] ( {x}, {(1.5 + 0.5*sin(x*30)) * cos(y)}, {(1.5 + 0.5*sin(x*30)) * sin(y)} );
% 2. Solid cap at x=3 (Back wall of the slice) \addplot3[ surf, domain=0:1, y domain=0:360, samples=2, samples y=36, fill=gray!30, faceted color=gray!50, line width=0.1pt ] ( {3}, {2.0 * x * cos(y)}, {2.0 * x * sin(y)} );
% 3. The highlighted differential slice crust (x from 3 to 3.5) \addplot3[ surf, domain=3:3.5, y domain=0:360, samples=4, samples y=36, fill=gray!50, faceted color=black!70, line width=0.3pt ] ( {x}, {(1.5 + 0.5*sin(x*30)) * cos(y)}, {(1.5 + 0.5*sin(x*30)) * sin(y)} );
% 4. Solid cap at x=3.5 (Front face of the slice) \addplot3[ surf, domain=0:1, y domain=0:360, samples=2, samples y=36, fill=gray!40, faceted color=black!70, line width=0.3pt ] ( {3.5}, {1.9829 * x * cos(y)}, {1.9829 * x * sin(y)} );
% 5. Front portion of the solid (x from 3.5 to 6) - TRANSPARENT \addplot3[ surf, domain=3.5:6, y domain=0:360, samples=15, samples y=36, fill=gray!30, draw=none, % No grid opacity=0.35 % See-through ] ( {x}, {(1.5 + 0.5*sin(x*30)) * cos(y)}, {(1.5 + 0.5*sin(x*30)) * sin(y)} );
% 6. End cap at x=6 - TRANSPARENT \addplot3[ surf, domain=0:1, y domain=0:360, samples=2, samples y=36, fill=gray!30, draw=none, opacity=0.35 ] ( {6}, {1.5 * x * cos(y)}, {1.5 * x * sin(y)} );
% --- Annotations ---
% Delta x dimension bracket at the top \draw[thick] (axis cs:3.0, 0, 2.15) -- (axis cs:3.0, 0, 2.4); \draw[thick] (axis cs:3.5, 0, 2.15) -- (axis cs:3.5, 0, 2.4); \draw[thick, <->] (axis cs:3.0, 0, 2.275) -- (axis cs:3.5, 0, 2.275) node[midway, above] {\(\Delta x\)};
% Area label directly on the face of the slice \node at (axis cs:3.5, 0, 0) {area \(A(x)\)};
% Volume label pointing to the bottom of the slice \node[anchor=north] at (axis cs:3.25, 0, -2.6) {volume \(\approx A(x)\Delta x\)}; \draw[thick, <-] (axis cs:3.25, 0, -2.05) -- (axis cs:3.25, 0, -2.6);
\end{axis} \end{tikzpicture}

\begin{tikzpicture} \begin{axis}[ view={35}{20}, width=0.85\textwidth, height=0.6\textwidth, grid=none, axis lines=center, xlabel={\(x\)}, ylabel={}, zlabel={}, xtick={0, 2.5, 4}, xticklabels={\(0\), \(x\), \(4\)}, ytick=\empty, ztick=\empty, xmin=-0.2, xmax=4.8, ymin=-2.5, ymax=2.5, zmin=-2.5, zmax=2.5, z buffer=sort ]
% 1. Back portion of the solid (x from 0 to 2.45) \addplot3[ surf, domain=0:2.45, y domain=0:360, samples=20, samples y=36, fill=gray!15, faceted color=gray!40, line width=0.1pt ] ( {x}, {sqrt(x) * cos(y)}, {sqrt(x) * sin(y)} );
% 2. Back cap of the disk slice (x=2.45) \addplot3[ surf, domain=0:1, y domain=0:360, samples=2, samples y=36, fill=gray!30, faceted color=gray!50, line width=0.1pt ] ( {2.45}, {sqrt(2.45) * x * cos(y)}, {sqrt(2.45) * x * sin(y)} );
% 3. The highlighted differential disk crust (x from 2.45 to 2.55) \addplot3[ surf, domain=2.45:2.55, y domain=0:360, samples=3, samples y=36, fill=gray!50, faceted color=black!70, line width=0.3pt ] ( {x}, {sqrt(x) * cos(y)}, {sqrt(x) * sin(y)} );
% 4. Front face of the disk slice (x=2.55) \addplot3[ surf, domain=0:1, y domain=0:360, samples=2, samples y=36, fill=gray!40, faceted color=black!70, line width=0.3pt ] ( {2.55}, {sqrt(2.55) * x * cos(y)}, {sqrt(2.55) * x * sin(y)} );
% 5. Front portion of the solid (x from 2.55 to 4) - TRANSPARENT \addplot3[ surf, domain=2.55:4, y domain=0:360, samples=15, samples y=36, fill=gray!30, draw=none, % No grid opacity=0.35 % See-through ] ( {x}, {sqrt(x) * cos(y)}, {sqrt(x) * sin(y)} );
% 6. End cap at x=4 - TRANSPARENT \addplot3[ surf, domain=0:1, y domain=0:360, samples=2, samples y=36, fill=gray!30, draw=none, opacity=0.35 ] ( {4}, {2 * x * cos(y)}, % sqrt(4) = 2 {2 * x * sin(y)} );
% --- Annotations ---
% Radius line directly on the front face of the disk slice \draw[thick, <->] (axis cs:2.55, 0, 0) -- (axis cs:2.55, 0, 1.5968) node[midway, right] {radius \(\sqrt{x}\)};
% Curve label floating along the upper edge \node[anchor=south] at (axis cs:1.5, 0, 1.4) {\(y=\sqrt{x}\)};
% Rotation label below the solid \node[anchor=north] at (axis cs:2.0, 0, -2.5) {rotation around \(x\)-axis};
\end{axis} \end{tikzpicture}

\begin{tikzpicture} \begin{axis}[ view={35}{20}, width=0.95\textwidth, height=0.65\textwidth, grid=none, axis lines=center, xlabel={}, ylabel={}, zlabel={}, ztick={0, 2, 2.2, 4}, zticklabels={\(0\), \(y\), \(y+\Delta y\), \(4\)}, xtick=\empty, ytick=\empty, xmin=-3.5, xmax=2.8, ymin=-2.8, ymax=2.8, zmin=-1.0, zmax=5.2, z buffer=sort ]
% 1. Back/Lower portion of the solid (y from 0 to 2) \addplot3[ surf, domain=0:2, y domain=0:360, samples=15, samples y=36, fill=gray!10, faceted color=gray!40, line width=0.1pt ] ( {sqrt(x) * cos(y)}, % Radius function r = sqrt(y) {sqrt(x) * sin(y)}, {x} );
% 2. Solid cap at y=2 (Back wall of the slice) \addplot3[ surf, domain=0:1, y domain=0:360, samples=2, samples y=36, fill=gray!30, faceted color=gray!50, line width=0.1pt ] ( {1.414 * x * cos(y)}, % Radius is exactly sqrt(2) \approx 1.414 at y=2 {1.414 * x * sin(y)}, {2} );
% 3. The highlighted differential slice crust (y from 2 to 2.2) \addplot3[ surf, domain=2:2.2, y domain=0:360, samples=4, samples y=36, fill=gray!50, faceted color=black!70, line width=0.3pt ] ( {sqrt(x) * cos(y)}, {sqrt(x) * sin(y)}, {x} );
% 4. Solid cap at y=2.2 (Front face of the slice) \addplot3[ surf, domain=0:1, y domain=0:360, samples=2, samples y=36, fill=gray!40, faceted color=black!70, line width=0.3pt ] ( {1.483 * x * cos(y)}, % Radius is approx sqrt(2.2) \approx 1.483 at y=2.2 {1.483 * x * sin(y)}, {2.2} );
% 5. Front/Glass upper portion of the solid (y from 2.2 to 4) - TRANSPARENT \addplot3[ surf, domain=2.2:4, y domain=0:360, samples=15, samples y=36, fill=gray!30, draw=none, % No grid opacity=0.35 % See-through ] ( {sqrt(x) * cos(y)}, {sqrt(x) * sin(y)}, {x} );
% 6. End/Glass cap at y=4 - TRANSPARENT \addplot3[ surf, domain=0:1, y domain=0:360, samples=2, samples y=36, fill=gray!30, draw=none, opacity=0.35 ] ( {2 * x * cos(y)}, % Radius function sqrt(4) = 2 {2 * x * sin(y)}, {4} );
% --- Annotations ---
% Axis labels corrected to the proper 3D mapping axes \node[anchor=west] at (axis cs:2.6, 0, 0) {\(x\)}; \node[anchor=south] at (axis cs:0, 0, 5.0) {\(y\)};
% Thickness dimension pointing to the FRONT-RIGHT edge of the slice \draw[thick, <-] (axis cs:1.45, 0, 2.1) -- (axis cs:2.3, 0, 2.1) node[right] {\(\Delta y\)};
% Area label directly on the visible face of the slice \node at (axis cs:0, 0, 2.2) {area \(A(y)\)};
% Volume label pointing to the FRONT edge of the slice \node[anchor=north] at (axis cs:0, -2.4, 1.2) {volume \(\approx A(y)\Delta y\)}; \draw[thick, <-] (axis cs:0, -1.45, 2.1) -- (axis cs:0, -2.4, 1.2);
% Top curve boundary label \node[anchor=south west] at (axis cs:0, 2.0, 4.0) {\(y=4\)};
% Surface label cleanly anchored along the FRONT-RIGHT edge \node[anchor=west] at (axis cs:1.75, 0, 3.0) {\(x=\sqrt{y}\)};
% Rotation label pulled closer to the center, and plot xmin expanded to give it room \draw[thick, <-] (axis cs:-0.2, 0, 4.6) -- (axis cs:-1.5, 0, 4.6) node[left] {rotation around \(y\)-axis};
\end{axis} \end{tikzpicture}
